    INSERT INTO options (id, question_id, option_text, is_correct, explanation)
    VALUES (gen_random_uuid(), question_id, 'Wenn unabhängige, mehrwertige Fakten (z. B. Betriebssysteme und Programmiersprachen einer Person) in einer einzigen Tabelle gespeichert werden, wodurch Redundanzen entstehen.', true, 'Die 4. Normalform betrifft "mehrwertige Abhängigkeiten". Das Beispiel im Text zeigt, dass die Speicherung von zwei unabhängigen 1:n-Beziehungen (Person->OS, Person->Sprache) in einer Tabelle zu Redundanz führt (Kartesisches Produkt) .');
