    INSERT INTO questions (id, quiz_id, question_text, question_type, order_index)
    VALUES (gen_random_uuid(), quiz_id, 'Was fordert die 5. Normalform (5NF) bezüglich Join-Abhängigkeiten?', 'MCQ', 2)
    RETURNING id INTO question_id;
    
    INSERT INTO options (id, question_id, option_text, is_correct)
    VALUES (gen_random_uuid(), question_id, 'Dass Tabellen nie geteilt werden dürfen (Join-Verbot).', false);
    INSERT INTO options (id, question_id, option_text, is_correct, explanation)
    VALUES (gen_random_uuid(), question_id, 'Dass innerhalb einer Tabelle nur triviale Join-Abhängigkeiten existieren dürfen (d. h. eine Zerlegung und erneute Verknüpfung erzeugt keine falschen/redundanten Tupel).', true, 'Die 5. Normalform ist verletzt, wenn eine Tabelle Informationen enthält, die eigentlich durch den Join mehrerer kleinerer Tabellen rekonstruiert werden könnten, ohne dass Informationen verloren gehen oder hinzukommen. Sie fordert, dass nur triviale Join-Abhängigkeiten existieren .');
