    INSERT INTO questions (id, quiz_id, question_text, question_type, order_index)
    VALUES (gen_random_uuid(), quiz_id, 'Wie unterscheidet sich das typische Marktverhalten eines Anbieters im Polypol (vollkommener Markt) von einem Angebotsmonopolisten?', 'MCQ', 2)
    RETURNING id INTO question_id;
    
    INSERT INTO options (id, question_id, option_text, is_correct)
    VALUES (gen_random_uuid(), question_id, 'Der Polypolist ist ein "Strategieanpasser", der Monopolist ist ein "Mengenanpasser".', false);
    INSERT INTO options (id, question_id, option_text, is_correct, explanation)
    VALUES (gen_random_uuid(), question_id, 'Der Polypolist ist ein "Mengenanpasser" (er passt seine Menge dem gegebenen Marktpreis an), während der Monopolist den Preis (und damit die Menge) strategisch setzen kann.', true, 'Im Polypol hat der Einzelne keinen Einfluss auf den Preis; er kann nur entscheiden, welche Menge er zum gegebenen Preis anbietet (Mengenanpasser). Der Monopolist beherrscht den Markt und kann den Preis strategisch so wählen, dass sein Gewinn maximal wird (Preissetzer/Strategie).');
    INSERT INTO options (id, question_id, option_text, is_correct)
    VALUES (gen_random_uuid(), question_id, 'Der Polypolist orientiert sich nur an den Reaktionen der Mitbewerber, der Monopolist nur an den Selbstkosten.', false);
