    VALUES (gen_random_uuid(), question_id, 'Der Polypolist muss eine Preissenkung durchführen, um seine Kapazitäten auszulasten, der Monopolist muss den Preis erhöhen, um Nachfrager zu finden.', false);
    INSERT INTO questions (id, quiz_id, question_text, question_type, order_index)
    VALUES (gen_random_uuid(), quiz_id, 'Nach einem Jahr, als erste Konkurrenten aufkommen, senkt es den Preis deutlich. Welche Strategie wurde verfolgt?', 'MCQ', 3)
