    INSERT INTO options (id, question_id, option_text, is_correct, explanation)
    VALUES (gen_random_uuid(), question_id, 'Skimmingstrategie (Abschöpfungsstrategie)', true, 'Die Skimming- oder Abschöpfungsstrategie ist exakt durch diesen Verlauf gekennzeichnet: ein hoher Einführungspreis, der die Zahlungsbereitschaft "abschöpft", solange der Wettbewerb gering ist. Der Preis wird später stufenweise gesenkt.');
