    INSERT INTO questions (id, quiz_id, question_text, question_type, order_index)
    VALUES (gen_random_uuid(), quiz_id, 'Welche Aussage über die ökonomische Kausalität und die Standard-Darstellung der Nachfragekurve in Diagrammen ist korrekt?', 'MCQ', 4)
    RETURNING id INTO question_id;
    
    INSERT INTO options (id, question_id, option_text, is_correct)
    VALUES (gen_random_uuid(), question_id, 'Die nachgefragte Menge ist die Ursache, der Marktpreis ist die Wirkung. Die Menge wird auf der Y-Achse abgetragen.', false);
    INSERT INTO options (id, question_id, option_text, is_correct, explanation)
    VALUES (gen_random_uuid(), question_id, 'Der Marktpreis ist die Ursache, die nachgefragte Menge ist die Wirkung. In der grafischen Darstellung werden die Achsen jedoch (mathematisch unüblich) vertauscht (Menge auf X, Preis auf Y).', true, 'Ökonomisch gesehen reagiert die Menge (Wirkung) auf den sich ändernden Preis (Ursache). Die Standard-Diagrammkonvention in der VWL vertauscht dies jedoch: Die unabhängige Variable (Preis) wird auf der Y-Achse und die abhängige Variable (Menge) auf der X-Achse gezeigt.');
    INSERT INTO options (id, question_id, option_text, is_correct)
    VALUES (gen_random_uuid(), question_id, 'Der Marktpreis und die nachgefragte Menge sind beides Ursachen, die zum Gleichgewichtspreis (Wirkung) führen.', false);
    INSERT INTO options (id, question_id, option_text, is_correct)
    VALUES (gen_random_uuid(), question_id, 'Der Marktpreis ist die Ursache, die nachgefragte Menge ist die Wirkung. Die Ursache (Preis) wird, wie in der Mathematik üblich, auf der X-Achse abgetragen.', false);
  END IF;
  
