    INSERT INTO questions (id, quiz_id, question_text, question_type, order_index)
    VALUES (gen_random_uuid(), quiz_id, 'Ein Unternehmen hat Lohneinzelkosten (LEK) von 200.000 € und Materialeinzelkosten (MEK) von 300.000 €. Die gesamten Gemeinkosten (GK) betragen 100.000 €. Die Gemeinkosten hängen stark von Lohn- und Materialeinzelkosten ab. Wie hoch ist der Gemeinkostenzuschlagssatz (GKZ)?', 'MCQ', 1)
    RETURNING id INTO question_id;
    
    INSERT INTO options (id, question_id, option_text, is_correct, explanation)
    VALUES (gen_random_uuid(), question_id, '20 %', true, 'Wenn die Gemeinkosten von beiden Einzelkostenarten abhängen, wird die Summe der Einzelkosten als Basis (Bezugsgröße) verwendet. Formel: GKZ = (GK / (LEK + MEK)) * 100. Rechnung: (100.000 € / (200.000 € + 300.000 €)) * 100 = (100.000 € / 500.000 €) * 100 = 0,2 * 100 = 20 %.');
