    INSERT INTO questions (id, quiz_id, question_text, question_type, order_index)
    VALUES (gen_random_uuid(), quiz_id, 'Im TDD-Beispiel getDMGrossPrice(): Was ist der Unterschied zwischen der "Green"-Phase und der "Refactor"-Phase?', 'MCQ', 3)
    RETURNING id INTO question_id;
    
    INSERT INTO options (id, question_id, option_text, is_correct)
    VALUES (gen_random_uuid(), question_id, '"Green" schreibt den Test (assertEquals), "Refactor" schreibt den Code (return...) [vgl. 2518, 2529].', false);
    INSERT INTO options (id, question_id, option_text, is_correct, explanation)
    VALUES (gen_random_uuid(), question_id, '"Green" schreibt Code, der den Test "mit den einfachsten... Mitteln besteht" (z.B. return 195.583); "Refactor" "integriert" den Code (z.B. return this.price * 1.95583) .', true, '"Green" bedeutet, Code zu schreiben, "der den Test mit den einfachsten möglichen Mitteln besteht" (eine "Brute-Force-Methode"). Im Beispiel war dies return 195.583;. "Refactor" bedeutet, diesen (einfachen) Code "vernünftig [zu] integrieren", d.h. ihn zu verallgemeinern und "aufzuräumen". Im Beispiel');
    INSERT INTO options (id, question_id, option_text, is_correct)
    VALUES (gen_random_uuid(), question_id, '"Green" erzeugt eine "BUILD SUCCESS"-Meldung; "Refactor" erzeugt eine "BUILD FAILURE"-Meldung [vgl. 2502, 2552].', false);
    INSERT INTO options (id, question_id, option_text, is_correct)
    VALUES (gen_random_uuid(), question_id, '"Green" wird in src/main/java gespeichert; "Refactor" wird in src/test/java gespeichert [vgl. 2438].', false);
  END IF;
  
